param([string]$SourceRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)),[Parameter(Mandatory=$true)][string]$OutputDirectory)
$ErrorActionPreference='Stop';$SourceRoot=[IO.Path]::GetFullPath($SourceRoot).TrimEnd('\','/');$OutputDirectory=[IO.Path]::GetFullPath($OutputDirectory).TrimEnd('\','/')
