if(-not [Environment]::Is64BitOperatingSystem){throw 'Build the Windows x64 installer on Windows x64.'}
$badOutput=$OutputDirectory -ieq $SourceRoot;foreach($directory in @('server','shared','client','scripts','tests','docs','dist')){if($OutputDirectory -ieq (Join-Path $SourceRoot $directory) -or $OutputDirectory.StartsWith((Join-Path $SourceRoot $directory)+'\',[StringComparison]::OrdinalIgnoreCase)){$badOutput=$true}};if($badOutput){throw 'Installer output must be outside application payload directories.'}
$package=Get-Content -LiteralPath (Join-Path $SourceRoot 'package.json') -Raw|ConvertFrom-Json;if($package.name -ne 'relay-agent-harness' -or $package.version -notmatch '^\d+\.\d+\.\d+$'){throw 'Invalid public Relay release.'}
if(-not(Test-Path -LiteralPath (Join-Path $SourceRoot 'dist\server\index.js')) -or -not(Test-Path -LiteralPath (Join-Path $SourceRoot 'node_modules\playwright\package.json'))){throw 'Build this clean public checkout first: npm ci, npm run check, npm run build.'}
$node=(Get-Command node.exe -ErrorAction Stop).Source;$csc=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe';if(-not(Test-Path -LiteralPath $csc)){throw 'Windows .NET Framework 4 compiler is unavailable on this build machine.'}
