$name='Relay-Setup-'+$package.version+'-beta-windows-x64.exe';foreach($file in @($name,'SHA256SUMS.txt','components.json','THIRD_PARTY_NOTICES.txt')){if(Test-Path -LiteralPath (Join-Path $OutputDirectory $file)){throw 'Release artifacts already exist; use a fresh output folder.'}}
$notices=Join-Path $build 'THIRD_PARTY_NOTICES.txt';$payload=Join-Path $build 'payload'
