try{$compilerArguments=@('/nologo','/target:winexe','/platform:x64','/optimize+','/r:System.Windows.Forms.dll','/r:System.Drawing.dll','/r:System.Web.Extensions.dll','/resource:engine.ps1,Relay.Engine.ps1','/resource:payload.zip,Relay.Payload.zip','/resource:payload-manifest.json,Relay.Manifest.json','/win32icon:Relay.ico','/out:RelaySetup.exe','ReleaseMetadata.cs','RelaySetup.cs');& $csc @compilerArguments;if($LASTEXITCODE -ne 0){throw 'Windows native installer compilation failed.'}}finally{Pop-Location}
$name='Relay-Setup-'+$package.version+'-beta-windows-x64.exe';$exe=Join-Path $OutputDirectory $name;if(Test-Path -LiteralPath $exe){throw 'A release executable already exists in this output folder; use a fresh output directory.'};Copy-Item -LiteralPath (Join-Path $build 'RelaySetup.exe') -Destination $exe
