$sums=@();foreach($file in @($name,'components.json','THIRD_PARTY_NOTICES.txt')){$sums+=((Hash (Join-Path $OutputDirectory $file))+'  '+$file)};[IO.File]::WriteAllText((Join-Path $OutputDirectory 'SHA256SUMS.txt'),(($sums -join "`n")+"`n"),[Text.UTF8Encoding]::new($false))
